insert into public.projects (id, title, description, category_id, rank, status, estimated_cost, spent, progress, store_name, store_url, inspiration_image, before_image, after_image, hotspot, price_history, notes, items, created_at, updated_by, updated_at, completed_at) values
  ('p-deck', 'Composite deck extension', 'Extend the back deck by 12 feet with composite boards, hidden fasteners, and a cable railing. Adds an outdoor dining zone off the kitchen slider.', 'yard', 1, 'in_progress', 4800, 2350, 45, 'Home Depot', 'https://www.homedepot.com/b/Lumber-Composite-Decking-Composite-Deck-Boards/N-5yc1vZbqm4', 'https://images.unsplash.com/photo-1591825729269-caeb344f6df2?auto=format&fit=crop&w=1200&q=70', 'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1200&q=70', null, '{"x":-0.9,"y":0.35,"z":-1.8}'::jsonb, '[{"date":"2026-05-18","price":5400,"note":"First quote"},{"date":"2026-07-02","price":5150},{"date":"2026-08-06","price":4950,"note":"Spring sale"},{"date":"2026-09-05","price":4800,"note":"Memorial Day pricing"}]'::jsonb, '[{"id":"n-deck-1","author":"Nate","text":"Measured the run this weekend — 12''4\" to the fence line, so we''re good on setback. Footings need to clear the sprinkler main on the east side.","createdAt":"2026-09-13T21:24:08.254Z"},{"id":"n-deck-2","author":"Melanie","text":"I like the cable railing in the inspiration pic way more than balusters. Adds ~$600 but worth it for the view.","createdAt":"2026-09-15T17:24:08.254Z"}]'::jsonb, '[{"id":"i-deck-1","name":"Composite deck boards (24)","price":2896,"url":"https://www.homedepot.com/b/Lumber-Composite-Decking-Composite-Deck-Boards/N-5yc1vZbqm4","purchased":true},{"id":"i-deck-2","name":"Cable railing kit, 40 ft","price":645,"url":"https://www.homedepot.com/s/cable%20railing%20kit","purchased":false},{"id":"i-deck-3","name":"Joist tape + hidden fasteners","price":168,"url":"https://www.homedepot.com/s/deck%20hidden%20fasteners","purchased":true},{"id":"i-deck-4","name":"Concrete footings (6)","price":210,"url":"https://www.homedepot.com/s/concrete%20deck%20footing","purchased":false}]'::jsonb, '2026-04-28', 'Nate', '2026-09-15T21:24:08.254Z', null),
  ('p-countertops', 'Quartz kitchen countertops', 'Replace laminate with honed quartz in Calacatta Laza, waterfall edge on the island, and a matching full-height backsplash behind the range.', 'kitchen', 2, 'planned', 6200, 0, 0, 'Cambria via Lowe''s', 'https://www.lowes.com/pl/kitchen-countertops-accessories/quartz-countertops/4294515760', 'https://images.unsplash.com/photo-1556911220-bff31c812dba?auto=format&fit=crop&w=1200&q=70', 'https://images.unsplash.com/photo-1600489000022-c2086d79f9d4?auto=format&fit=crop&w=1200&q=70', null, '{"x":-0.9,"y":0.62,"z":-1.28}'::jsonb, '[{"date":"2026-06-17","price":6900,"note":"Showroom quote"},{"date":"2026-07-22","price":6550},{"date":"2026-08-26","price":6200,"note":"Contractor referral discount"}]'::jsonb, '[{"id":"n-counter-1","author":"Melanie","text":"Showroom visit booked for Saturday 10am. Bring the cabinet door for color matching!","createdAt":"2026-09-14T19:24:08.254Z"}]'::jsonb, '[{"id":"i-ct-1","name":"Calacatta Laza quartz slabs","price":4980,"url":"https://www.lowes.com/pl/kitchen-countertops-accessories/quartz-countertops/4294515760","purchased":false},{"id":"i-ct-2","name":"Undermount workstation sink","price":489,"url":"https://www.lowes.com/pl/kitchen-sinks/4294736221","purchased":false},{"id":"i-ct-3","name":"Backsplash panel cut","price":731,"purchased":false}]'::jsonb, '2026-06-12', 'Melanie', '2026-09-14T21:24:08.254Z', null),
  ('p-shower', 'Primary bath walk-in shower', 'Convert the tub to a curbless walk-in shower with large-format porcelain, a linear drain, and a rainfall head. Niche with LED strip.', 'bathrooms', 3, 'idea', 7400, 0, 0, 'Floor & Decor', 'https://www.flooranddecor.com/', 'https://images.unsplash.com/photo-1552321554-5fefe8c9ef14?auto=format&fit=crop&w=1200&q=70', null, null, '{"x":1.05,"y":1.6,"z":0}'::jsonb, '[{"date":"2026-07-17","price":7800},{"date":"2026-08-21","price":7400}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '2026-07-07', 'Melanie', '2026-09-12T17:24:08.254Z', null),
  ('p-fireplace', 'Fireplace feature wall', 'Floor-to-ceiling fluted oak surround with a 60" linear electric fireplace, hidden media conduit, and picture-light sconces.', 'living-room', 4, 'in_progress', 2900, 1100, 35, 'Wayfair', 'https://www.wayfair.com/home-improvement/sb0/electric-fireplaces-c1876340.html', 'https://images.unsplash.com/photo-1600210492486-724fe5c67fb0?auto=format&fit=crop&w=1200&q=70', 'https://images.unsplash.com/photo-1600121848594-d8644e57abab?auto=format&fit=crop&w=1200&q=70', null, '{"x":-1.76,"y":0.62,"z":0.05}'::jsonb, '[{"date":"2026-06-07","price":3200},{"date":"2026-08-01","price":3050},{"date":"2026-09-03","price":2900,"note":"Fireplace insert on sale"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '2026-05-28', 'Nate', '2026-09-15T18:24:08.254Z', null),
  ('p-ev-charger', 'EV charger install', 'Level 2 wall charger on a dedicated 60A circuit, cable management dock, and a weatherproof exterior outlet for the driveway.', 'garage', 5, 'planned', 1250, 0, 0, 'Amazon', 'https://www.amazon.com/s?k=level+2+ev+charger', 'https://images.unsplash.com/photo-1593941707882-a5bba14938c7?auto=format&fit=crop&w=1200&q=70', null, null, '{"x":2.28,"y":0.45,"z":0.6}'::jsonb, '[{"date":"2026-04-18","price":1650},{"date":"2026-06-12","price":1480},{"date":"2026-07-27","price":1340},{"date":"2026-09-08","price":1250,"note":"Lowest tracked — good time to buy"}]'::jsonb, '[{"id":"n-ev-1","author":"Nate","text":"Panel has room for a 60A breaker — confirmed with the electrician. Install quote was $420 on top of the unit.","createdAt":"2026-09-14T16:24:08.254Z"}]'::jsonb, '[{"id":"i-ev-1","name":"Level 2 wall charger (48A)","price":649,"url":"https://www.amazon.com/s?k=level+2+ev+charger+48a","purchased":false},{"id":"i-ev-2","name":"60A breaker + 6AWG wire run","price":420,"purchased":false},{"id":"i-ev-3","name":"Cable dock + weatherproof outlet","price":181,"url":"https://www.amazon.com/s?k=ev+cable+dock","purchased":false}]'::jsonb, '2026-04-08', 'Nate', '2026-09-14T17:24:08.254Z', null),
  ('p-walkway', 'Paver walkway & landscape lighting', 'Curved paver path from the driveway to the back gate with low-voltage bollard lights and fresh mulch beds along the fence line.', 'yard', 6, 'idea', 2100, 0, 0, 'Lowe''s', 'https://www.lowes.com/pl/pavers-stepping-stones/4294612564', 'https://images.unsplash.com/photo-1558904541-efa843a96f01?auto=format&fit=crop&w=1200&q=70', null, null, '{"x":-0.35,"y":0.08,"z":2.1}'::jsonb, '[{"date":"2026-08-06","price":2250},{"date":"2026-09-06","price":2100}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '2026-07-29', 'Melanie', '2026-09-10T23:24:08.254Z', null),
  ('p-front-door', 'Cedar porch surround & house numbers', 'Wrap the front porch posts in clear cedar, add a modern horizontal address plaque, and swap the porch light for a warm sconce pair.', 'outside', 7, 'planned', 980, 0, 0, 'Etsy', 'https://www.etsy.com/search?q=modern+house+numbers', 'https://images.unsplash.com/photo-1580587771525-78b9dba3b914?auto=format&fit=crop&w=1200&q=70', null, null, '{"x":-0.35,"y":0.98,"z":1.27}'::jsonb, '[{"date":"2026-08-16","price":1050},{"date":"2026-09-10","price":980}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '2026-08-08', null, null, null),
  ('p-mel-office', 'Built-in desk wall — Mel', 'Wall-to-wall built-in with a floating walnut desk, closed storage below, open shelving with picture lights, and a cork pin rail.', 'office-mel', 8, 'idea', 3400, 0, 0, 'IKEA + custom fronts', 'https://www.ikea.com/us/en/rooms/home-office/', 'https://images.unsplash.com/photo-1593062096033-9a26b09da705?auto=format&fit=crop&w=1200&q=70', null, null, '{"x":-1.74,"y":1.62,"z":-0.3}'::jsonb, '[{"date":"2026-08-25","price":3400}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '2026-08-20', null, null, null),
  ('p-nate-office', 'Acoustic panels & studio lighting — Nate', 'PET felt acoustic panels in a staggered layout, bias lighting behind the monitors, and a ceiling-mounted key light for calls.', 'office-nate', 9, 'idea', 760, 0, 0, 'Amazon', 'https://www.amazon.com/s?k=acoustic+panels', 'https://images.unsplash.com/photo-1598550476439-6847785fcea6?auto=format&fit=crop&w=1200&q=70', null, null, null, '[{"date":"2026-08-13","price":820},{"date":"2026-09-09","price":760}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '2026-08-05', null, null, null),
  ('p-mudroom', 'Entry mudroom bench & hooks', 'Board-and-batten wall with a white oak bench, shoe cubbies underneath, matte black hooks, and a slim console shelf with hidden outlets.', 'entry-room', 10, 'planned', 1150, 0, 0, 'Home Depot', 'https://www.homedepot.com/b/Storage-Organization-Entryway-Furniture/N-5yc1vZ2fkp7cd', 'https://images.unsplash.com/photo-1600607687920-4e2a09cf159d?auto=format&fit=crop&w=1200&q=70', null, null, '{"x":0.12,"y":0.45,"z":1.26}'::jsonb, '[{"date":"2026-07-25","price":1280},{"date":"2026-09-01","price":1150}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '2026-07-19', 'Melanie', '2026-09-11T23:24:08.254Z', null),
  ('p-garage-storage', 'Garage slat-wall storage system', 'Full slat-wall panels on the long wall, overhead ceiling racks for bins, and a fold-down workbench. Everything off the floor.', 'garage', 11, 'done', 1600, 1540, 100, 'Costco', 'https://www.costco.com/garage-storage.html', 'https://images.unsplash.com/photo-1558036117-15d82a90b9b1?auto=format&fit=crop&w=1200&q=70', 'https://images.unsplash.com/photo-1601055283742-8b27e81b5553?auto=format&fit=crop&w=1200&q=70', 'https://images.unsplash.com/photo-1558036117-15d82a90b9b1?auto=format&fit=crop&w=1200&q=70', '{"x":1.6,"y":0.75,"z":1.27}'::jsonb, '[{"date":"2026-02-17","price":1850},{"date":"2026-03-29","price":1700},{"date":"2026-04-18","price":1600,"note":"Bought at this price"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '2026-02-07', 'Nate', '2026-08-17T19:24:08.254Z', '2026-08-17T19:24:08.254Z'),
  ('p-bedroom-wall', 'Master bedroom accent wall & blackout', 'Limewash accent wall behind the bed, floating nightstands with sconces, and motorized blackout roller shades on both windows.', 'master-bedroom', 12, 'idea', 1900, 0, 0, 'Smith & Noble', 'https://www.smithandnoble.com/', 'https://images.unsplash.com/photo-1616594039964-ae9021a400a0?auto=format&fit=crop&w=1200&q=70', null, null, '{"x":0.45,"y":1.62,"z":0.97}'::jsonb, '[{"date":"2026-08-18","price":2050},{"date":"2026-09-12","price":1900}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '2026-08-11', 'Melanie', '2026-09-13T21:24:08.254Z', null),
  ('p-gutter-drainage', 'Gutter drainage & foundation seal', 'Bury downspout extensions 10 ft from the foundation, regrade the north bed, and seal the hairline crack in the basement wall.', 'house-repairs', 13, 'planned', 850, 0, 0, 'Menards', 'https://www.menards.com/', 'https://images.unsplash.com/photo-1570129477492-45c003edd2be?auto=format&fit=crop&w=1200&q=70', null, null, '{"x":1.15,"y":0.2,"z":-1.32}'::jsonb, '[{"date":"2026-08-01","price":900},{"date":"2026-09-04","price":850}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '2026-07-27', 'Nate', '2026-09-07T15:24:08.254Z', null),
  ('p-window-seal', 'Reseal south-facing windows', 'Replace weather stripping and exterior caulk on the three south windows that fog up. Check for failed glazing seals while at it.', 'house-repairs', 14, 'idea', 240, 0, 0, 'Ace Hardware', 'https://www.acehardware.com/', 'https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=1200&q=70', null, null, '{"x":-0.7,"y":1.62,"z":0.97}'::jsonb, '[{"date":"2026-08-29","price":240}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '2026-08-27', null, null, null)
